#include <stdio.h>
#include <stdlib.h>

struct treap_node {
    int key;
    int priority;
    struct treap_node *left;
    struct treap_node *right;
};

struct treap_node *root = NULL;

struct treap_node* create_node(int key, int priority) {
    struct treap_node *n = (struct treap_node*)malloc(sizeof(struct treap_node));
    if(!n) exit(1);
    n->key = key;
    n->priority = priority;
    n->left = NULL;
    n->right = NULL;
    return n;
}

struct treap_node* right_rotate(struct treap_node *y) {
    struct treap_node *x = y->left;
    struct treap_node *T2 = x->right;
    x->right = y;
    y->left = T2;
    return x;
}

struct treap_node* left_rotate(struct treap_node *x) {
    struct treap_node *y = x->right;
    struct treap_node *T2 = y->left;
    y->left = x;
    x->right = T2;
    return y;
}

struct treap_node* insert_node(struct treap_node *node, int key, int priority) {
    if (!node) return create_node(key, priority);
    if (key < node->key) {
        node->left = insert_node(node->left, key, priority);
        if (node->left->priority > node->priority) {
            node = right_rotate(node);
        }
    } else if (key > node->key) {
        node->right = insert_node(node->right, key, priority);
        if (node->right->priority > node->priority) {
            node = left_rotate(node);
        }
    }
    return node;
}

void treap_insert(int key, int priority) {
    root = insert_node(root, key, priority);
}

struct treap_node* delete_node(struct treap_node *node, int key) {
    if (!node) return node;

    if (key < node->key) {
        node->left = delete_node(node->left, key);
    } else if (key > node->key) {
        node->right = delete_node(node->right, key);
    } else {
        if (!node->left && !node->right) {
            free(node);
            return NULL;
        }
        else if (node->left && !node->right) {
            node = right_rotate(node);
            node->right = delete_node(node->right, key);
        }
        else if (!node->left && node->right) {
            node = left_rotate(node);
            node->left = delete_node(node->left, key);
        }
        else {
            if (node->left->priority > node->right->priority) {
                node = right_rotate(node);
                node->right = delete_node(node->right, key);
            } else {
                node = left_rotate(node);
                node->left = delete_node(node->left, key);
            }
        }
    }
    return node;
}

void treap_delete(int key) {
    root = delete_node(root, key);
}

int validate_bst(struct treap_node *node, long long min, long long max) {
    if (!node) return 1;
    if (node->key <= min || node->key >= max) return 0;
    return validate_bst(node->left, min, node->key) && validate_bst(node->right, node->key, max);
}

int validate_heap(struct treap_node *node) {
    if (!node) return 1;
    if (node->left && node->left->priority > node->priority) return 0;
    if (node->right && node->right->priority > node->priority) return 0;
    return validate_heap(node->left) && validate_heap(node->right);
}

int main() {
    srand(42);
    int keys[5000];
    for (int i = 0; i < 5000; i++) keys[i] = i;
    for (int i = 4999; i > 0; i--) {
        int j = rand() % (i + 1);
        int t = keys[i];
        keys[i] = keys[j];
        keys[j] = t;
    }
    for (int i = 0; i < 5000; i++) {
        treap_insert(keys[i], rand());
    }
    for (int i = 0; i < 2500; i++) {
        treap_delete(keys[i]);
    }
    if (validate_bst(root, -10000000000LL, 10000000000LL) && validate_heap(root)) {
        printf("FLAG: Treap Success!\n");
    } else {
        printf("FAILED\n");
        return 1;
    }
    return 0;
}
